namespace NHAMBS.Circular

open System.IO
open FSharp.Data

/// Typed view of a CMHC 2834 NHA MBS Information Circular.
///
/// The provider reads `schema/cmhc-2834-i-v2-extended-en.provider.schema.json`,
/// a flattened copy of the real Draft 2020-12 schema. The copy is generated by
/// `generate-provider-schema.fsx` because FSharp.Data's schema reader does not
/// resolve `$ref`. The real schema remains the source of truth and is embedded
/// in this assembly for validation by `Schema.validate`.
type Circular =
    JsonProvider<
        "",
        Schema="schema/cmhc-2834-i-v2-extended-en.provider.schema.json",
        EmbeddedResource="NHAMBS.Circular, NHAMBS.Circular.schema.cmhc-2834-i-v2-extended-en.provider.schema.json"
     >

[<RequireQualifiedAccess>]
module Circular =

    /// Parse JSON that is already known to match the schema.
    let parse (json: string) : Circular.Root = Circular.Parse json

    /// Validate JSON against the embedded schema, then parse it.
    let parseValidated (json: string) : Result<Circular.Root, ValidationError list> =
        match Schema.validate json with
        | Error errors -> Error errors
        | Ok _ -> Ok(parse json)

    /// Load one circular file, validate it, and return its typed representation.
    let load (path: string) : Result<Circular.Root, ValidationError list> = File.ReadAllText path |> parseValidated

    /// Load a sequence of circular files. Each result keeps its source path so
    /// that failures can be reported without aborting the whole batch.
    let loadMany (paths: string seq) =
        paths |> Seq.map (fun path -> path, load path) |> Seq.toArray

    /// Load every `*.json` file directly under a directory.
    let loadDirectory (directory: string) =
        Directory.EnumerateFiles(directory, "*.json") |> loadMany

    /// Small projection that is useful when indexing a folder of circulars.
    let summary (circular: Circular.Root) =
        {|
            RateType = circular.RateType
            PoolType = circular.PoolType
            PoolNumber = circular.Mbs.PoolNumber
            Issuer = circular.Parties.IssuerName
            AggregatePrincipalAmount = circular.Mbs.AggregatePrincipalAmount
            IssueDate = circular.Mbs.IssueDate
        |}
